export interface Request {
  path: string;
}

export interface Reply {
  send(body: unknown): void;
}

export type Handler = (request: Request, reply: Reply) => void;

export interface PluginOptions {
  prefix?: string;
}

export interface App {
  get(path: string, handler: Handler): this;
  /** Runs `plugin` with an app whose routes are served under `options.prefix`. */
  register(plugin: (app: App) => void | Promise<void>, options?: PluginOptions): this;
}

/** A second server of the same package, with a `register` of its own. */
export declare class Admin {
  get(path: string, handler: Handler): this;
  /** Runs `plugin` with an admin whose routes are served under `options.prefix`. */
  register(plugin: (admin: Admin) => void | Promise<void>, options?: PluginOptions): this;
}

declare function server(): App;
export default server;
